{
  "name": "Galil多轴运动控制器",
  "name_en": "Galil Multi-Axis Motion Controller",
  "manufacturer": "Galil",
  "description": "这是一类用于控制多轴电机运动的运动控制器，可驱动实验中的线性平台、位移轴或机械机构，并提供数字/模拟I/O接口用于联锁、触发和信号读取。它常用于精密定位、自动扫描、样品移动和实验装置集成控制。",
  "description_en": "This is a multi-axis motion controller used to drive motorized stages, translation axes, or other laboratory mechanisms, while also providing digital and analog I/O for interlocks, triggering, and signal readback. It is commonly used for precise positioning, automated scanning, sample movement, and integrated instrument control.",
  "tag_hints": [
    "multi-axis motion control",
    "motorized stage control",
    "precision positioning",
    "digital I/O",
    "analog input",
    "automated scanning",
    "Galil controller"
  ],
  "actions": [
    {
      "action_name": "auto-motor_move",
      "description": "按指定轴、距离/位置、速度和模式移动电机。",
      "description_en": "Move a motor axis with the specified axis, distance/position, speed, and motion mode."
    },
    {
      "action_name": "auto-motor_move_live",
      "description": "以实时运动序列按指定轴、距离/位置、速度和模式移动电机。",
      "description_en": "Move a motor axis using a live motion sequence with the specified axis, distance/position, speed, and mode."
    },
    {
      "action_name": "auto-motor_disconnect",
      "description": "断开与运动控制器的连接。",
      "description_en": "Disconnect from the motion controller."
    },
    {
      "action_name": "auto-query_all_axis_positions",
      "description": "查询所有轴的当前位置。",
      "description_en": "Query the current positions of all axes."
    },
    {
      "action_name": "auto-query_axis",
      "description": "查询指定轴的当前位置。",
      "description_en": "Query the current position of a specified axis."
    },
    {
      "action_name": "auto-query_moving",
      "description": "查询控制器是否有任意轴正在运动。",
      "description_en": "Query whether any axis is currently moving."
    },
    {
      "action_name": "auto-motor_off",
      "description": "关闭指定轴的电机使能/驱动。",
      "description_en": "Disable the motor drive for the specified axis."
    },
    {
      "action_name": "auto-motor_on",
      "description": "开启指定轴的电机使能/驱动。",
      "description_en": "Enable the motor drive for the specified axis."
    },
    {
      "action_name": "auto-motor_stop",
      "description": "立即停止所有轴的运动。",
      "description_en": "Immediately stop motion on all axes."
    },
    {
      "action_name": "auto-read_analog_in",
      "description": "读取指定模拟输入端口的数值。",
      "description_en": "Read the value of a specified analog input port."
    },
    {
      "action_name": "auto-read_digital_in",
      "description": "读取指定数字输入端口的状态。",
      "description_en": "Read the state of a specified digital input port."
    },
    {
      "action_name": "auto-read_digital_out",
      "description": "读取指定数字输出端口的当前输出状态。",
      "description_en": "Read the current output state of a specified digital output port."
    },
    {
      "action_name": "auto-set_analog_out",
      "description": "设置受支持模块上的模拟输出值。",
      "description_en": "Set the analog output value on a supported module."
    },
    {
      "action_name": "auto-digital_out_on",
      "description": "将指定数字输出端口置为开启。",
      "description_en": "Turn a specified digital output port on."
    },
    {
      "action_name": "auto-digital_out_off",
      "description": "将指定数字输出端口置为关闭。",
      "description_en": "Turn a specified digital output port off."
    },
    {
      "action_name": "auto-infinite_digital_cycles",
      "description": "让指定数字输出端口持续进行开关循环。",
      "description_en": "Continuously cycle a specified digital output port on and off."
    },
    {
      "action_name": "auto-break_infinite_digital_cycles",
      "description": "停止指定数字输出端口的持续开关循环。",
      "description_en": "Stop the continuous on/off cycling of a specified digital output port."
    },
    {
      "action_name": "auto-shutdown_event",
      "description": "在关闭时安全断开运动控制器连接。",
      "description_en": "Safely disconnect the motion controller during shutdown."
    }
  ]
}

